#!/usr/bin/env python3
"""Deterministic authoring of original Russian lessons. No network or generated filler."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
TARGET=ROOT/'apps/unity/Assets/_HOSTFALL/Content/Resources/FieldContent.json'
data=json.loads(TARGET.read_text())
keep={'terminal','process','filesystem','ip','server','http','container','kubernetes'}
articles=[a for a in data['articles'] if a['id'] in keep]
for i,a in enumerate(articles):
    a.update(track='',order=i,unlockStage={'ip':1,'server':2,'http':2,'container':2,'kubernetes':3}.get(a['id'],0))
    a['prerequisites']=[p for p in a['prerequisites'] if p in keep]
    a['relatedConcepts']=[p for p in a['relatedConcepts'] if p in keep]
    # The archive is self-contained. Editor references never become a player reading assignment.
    a['deeperStudy']=''
SOURCES={
 'python':'https://docs.python.org/3.13/tutorial/',
 'cpp':'https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines',
 'systems':'https://www.freedesktop.org/software/systemd/man/latest/systemctl.html',
 'network':'https://www.rfc-editor.org/rfc/rfc9293',
 'security':'https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html',
 'sysprog':'https://docs.kernel.org/filesystems/path-lookup.html',
 'infra':'https://kubernetes.io/docs/concepts/workloads/controllers/deployment/'
}
def add(id,title,category,stage,prereqs,summary,body,code,expected,exercise,mistake,language='text',track='',source=None):
    articles.append(dict(id=id,title=title,category=category,track=track,unlockStage=stage,order=len(articles),
        summary=summary,body=body,purpose='',realExample='',gameApplications='',exercise=exercise,mistakes=mistake,deeperStudy='',
        verifiedAt='2026-11-07',technologyVersion='C++20' if track=='cpp' else 'Python 3' if track=='python' else 'Concepts',
        reviewStatus='Original authored lesson; executable examples checked separately',
        relatedConcepts=prereqs[-2:],prerequisites=prereqs,commands=[],officialSources=[source or SOURCES.get(track,SOURCES['systems'])],
        examples=[dict(language=language,code=code,expected=expected,verification='Authoring check; not player code execution')],quickCommands=[],x=0,y=0))
def py(key,title,stage,parent,summary,body,code,expected,exercise,mistake,source=None):
    add('python.'+key,title,'Программирование',stage,['python.'+p for p in parent],summary,body,code,expected,exercise,mistake,'python','python',source)
def cpp(key,title,stage,parent,summary,body,code,expected,exercise,mistake,headers='iostream',declarations='',source=None):
    program=''.join('#include <'+h+'>\n' for h in headers.split())+'\n'+(declarations+'\n\n' if declarations else '')+'int main() {\n'+''.join('    '+line+'\n' for line in code.splitlines())+'}\n'
    add('cpp.'+key,title,'Программирование',stage,['cpp.'+p for p in parent],summary,body,program,expected,exercise,mistake,'cpp','cpp',source)

