# Only current catalog references are retained; retired JavaScript/HTML/CSS never enter a language branch.
ids={a['id'] for a in articles}
for a in articles:
    a['relatedConcepts']=[p for p in a['relatedConcepts'] if p in ids]
    a['prerequisites']=[p for p in a['prerequisites'] if p in ids]
for entry in data['quests'] + data['documents']:
    entry['concepts']=list(dict.fromkeys('sys.service-policy' if p=='algorithm' else 'terminal' if p=='language' else p for p in entry['concepts']))
# Every lesson has an editorial source; trusted examples can be overridden there too.
editorial=ROOT/'docs/knowledge/editorial/lessons.json'
copy=json.loads(editorial.read_text(encoding='utf-8'))
assert set(copy)==ids, 'Editorial coverage must match all catalog IDs'
for article in articles:
    article.update(copy[article['id']])
for collection,filename in [('quests','quests.json'),('documents','documents.json')]:
    replacements=json.loads((editorial.parent/filename).read_text(encoding='utf-8'))
    assert set(replacements)=={entry['id'] for entry in data[collection]}
    for entry in data[collection]:
        entry.update(replacements[entry['id']])
data['articles']=articles
data['links']=[dict(from_=p,to=a['id'],relation='Requires') for a in articles for p in a['prerequisites']]
for link in data['links']:link['from']=link.pop('from_')
data['links'] += [dict(**{'from':'process','to':'infra.desired','relation':'RelatedTo'}),dict(**{'from':'terminal','to':'filesystem','relation':'UsedBy'})]
assert len(articles)==96, len(articles)
assert len(ids)==96
TARGET.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print('Authored catalog:',len(articles),'articles; 24 C++, 24 Python, 48 shared; 72 per campaign')
